/**
 * @file  PresetsTable.hpp
 * @brief Internal: the built-in preset table, shared by the generated Presets.cpp (definition)
 *        and Workout.cpp (preset(), findPreset()). Not part of the public score API.
 */

#pragma once

#include "score/Workout.hpp"

namespace score {

/// Defined in Presets.cpp, generated by tools/gen_presets.py from presets.json.
extern const Workout kPresets[kPresetCount];

/// One preset step: spot, goal type and value, rest after the step in seconds.
constexpr Step step(Spot s, GoalType t, uint16_t value, uint8_t rest)
{
    return { static_cast<uint8_t>(s), rest, { static_cast<uint8_t>(t), 0, value } };
}

} // namespace score
